import csv
H="item_id,ac_relevant,ac_kind,principals_needed,observable_via_http,contract_operation,contract_security,policy_in_contract,fix_location,confidence,locators,rationale".split(",")
NA=["NO"]+["NA"]*7
def no(i,c,l,r): return [i]+NA[:1]+["NA"]*7+[c,l,r]
R=[
["A113","YES","TENANT_ISOLATION","TWO_SAME_ROLE","YES","PRESENT","NOT_DECLARED","NO","HANDLER","2","diff.patch:internal/handlers/v1alpha1/source.go; contract api__v1alpha1__openapi.yaml deleteSources","Any authenticated user could call DELETE /api/v1/sources, which removed all sources of every user/organisation without owner filtering. Fix removed the endpoint."],
no("A114","3","diff.patch CoAPHeaderFilterStrategy","CoAP header injection in a CoAP component, not an HTTP access-control decision; fields NA."),
["A115","YES","FUNCTION_LEVEL","TWO_ROLES","YES","ABSENT","NA","NO","MIDDLEWARE_FILTER","2","diff.patch:pkg/api/pluginproxy/ds_proxy.go hasAccessToRoute","Plugin data source route RBAC action was checked globally, not per datasource; a user holding the action on any other datasource could use plugin routes on a datasource where it lacked it."],
["A116","YES","OBJECT_LEVEL","TWO_ROLES","YES","PRESENT","NOT_DECLARED","NO","HANDLER","2","diff.patch:server/etcdserver/api/v3rpc/watch.go:260-320; contract rpc.swagger.json /v3/watch","User with READ on one key could open a from-key watch (range_end normalised before permission check) and receive events for all keys at or after it."],
no("A117","2","diff.patch:router/oauth2/authorization_endpoint.go:203","OAuth prompt=none consent check used empty scope set so broader scopes were issued; treated as OAuth authorization-flow/token issuance logic, not object/function access control."),
["A118","YES","FUNCTION_LEVEL","TWO_ROLES","YES","UNCLEAR","NA","NO","SERVICE_LOGIC","2","diff.patch:[service.go] clearUserPermissionCache","After an admin revoked a user's permission to create service account tokens, cached permissions let the user keep minting tokens for seconds. Fix invalidates the permission cache on permission change."],
["A119","YES","TENANT_ISOLATION","TWO_SAME_ROLE","UNCLEAR","ABSENT","NA","NO","SERVICE_LOGIC","2","diff.patch:internal/services/dispatcher/server_v1.go:362; dispatcher_v1.go durableInvocationsKey","A tenant A worker registering tenant B's durable task id on a gRPC stream received tenant B's callback payload; callback routing was keyed without tenant. Stream API not in REST contract."],
["A120","YES","TENANT_ISOLATION","ONE","YES","PRESENT","NOT_DECLARED","NO","SERVICE_LOGIC","2","diff.patch:controller/appcontroller.go getResourceTree; server/application/application.go ListResourceEvents; contract swagger.json:626","A user with RBAC on an application could read resources, events and logs, or act on, objects in the destination cluster outside the project's permitted kinds/namespaces; fix filters by project permission."],
["A121","YES","OBJECT_LEVEL","TWO_SAME_ROLE","YES","PRESENT","NOT_DECLARED","NO","HANDLER","3","diff.patch:controllers/user.go:331-370; contract swagger.yaml PUT /api/users/{username}","Any authenticated user could update another user's record (including password) via PUT /api/users/{username}; also could set IsAdmin. Fix checks caller equals target or admin."],
["A122","YES","MISSING_AUTHENTICATION","NONE","YES","ABSENT","NA","NO","MIDDLEWARE_FILTER","2","diff.patch:internal/api/v1/v1.go:437 system.Install","System API routes were installed on the party without JWT/auth handlers, so they were reachable without credentials; fix mounts them on the authenticated party."],
["A123","YES","FUNCTION_LEVEL","TWO_ROLES","YES","PRESENT","DECLARED","NO","SERVICE_LOGIC","3","diff.patch:backend/src/apiserver/server/pipeline_server.go:1262; contract DELETE /apis/v2beta1/pipelines/{pipeline_id}","Any authenticated user could modify or delete shared pipelines (empty namespace) because authorization was skipped for all verbs; fix requires RBAC in system namespace for writes."],
["A124","YES","MISSING_AUTHENTICATION","NONE","YES","PRESENT","NOT_DECLARED","NO","MIDDLEWARE_FILTER","3","diff.patch:manager/router/router.go:201; contract api/v1/jobs","Job endpoints (/api/v1/jobs) lacked JWT and RBAC middleware, letting anonymous callers list, create, modify and delete jobs."],
["A125","YES","FUNCTION_LEVEL","TWO_ROLES","YES","PRESENT","NOT_DECLARED","NO","SERVICE_LOGIC","2","diff.patch admission.go getMatchingPolicies/authorizedForPolicy; contract POST /api/v1/namespaces/{namespace}/pods","PodSecurityPolicy admission treated missing service-account info as authorized, so a user not entitled to a policy could create pods under any existing PSP."],
["A126","YES","MISSING_AUTHENTICATION","NONE","YES","ABSENT","NA","NO","SERVICE_LOGIC","2","diff.patch ObjectEntryHelper.java setPermissionChecker removed","Guest users could read object entries via API Builder endpoints because requests ran with the object definition owner's permission checker. Dynamic endpoints not in provided contract."],
["A127","YES","OBJECT_LEVEL","TWO_SAME_ROLE","YES","ABSENT","NA","NO","HANDLER","2","diff.patch:pkg/routes/caldav/listStorageProvider.go:175-230","An authenticated CalDAV user knowing a task UID could read tasks of projects they had no access to via GET or multiget REPORT. CalDAV not in swagger."],
["A128","YES","FUNCTION_LEVEL","TWO_ROLES","YES","ABSENT","NA","NO","HANDLER","2","diff.patch:controllers/scim.go:21","SCIM endpoints (user creation) were served without an admin check, so non-admin callers could manage users; fix adds RequireAdmin. Unclear if anonymous callers also succeeded."],
]
with open("codes_H1.csv","w",newline="") as f:
    w=csv.writer(f); w.writerow(H)
    for r in R:
        if len(r)==5: r=[r[0],"NO"]+["NA"]*7+r[1:]
        assert len(r)==12,r[0]
        w.writerow(r)
